package serialize

import (
	"regexp"

	"github.com/ducconit/figma-cli/internal/extractors"
)

var autoGeneratedNameRegex = regexp.MustCompile(
	`^(?:Frame|Rectangle|Ellipse|Line|Vector|Group|Component|Instance|Polygon|Star|Text|Image|Slice|Section|Boolean|Union|Subtract|Intersect|Exclude|Arrow)\s+\d+$`,
)

// IsAutoGeneratedName returns true if the node name is a default numbered Figma layer name (e.g. "Frame 12").
func IsAutoGeneratedName(name string) bool {
	return autoGeneratedNameRegex.MatchString(name)
}

// IsNoiseName returns true if the node is a TEXT layer (whose name duplicates or lags behind its text content)
// or has an auto-generated numbered Figma layer name.
func IsNoiseName(name, nodeType string) bool {
	if name == "" {
		return true
	}
	return nodeType == "TEXT" || IsAutoGeneratedName(name)
}

// StripNoiseNames clones the node tree and strips noise names from all nodes (resolving template types when needed).
func StripNoiseNames(nodes []*extractors.SimplifiedNode, elements map[string]extractors.ElementBody) []*extractors.SimplifiedNode {
	if len(nodes) == 0 {
		return nil
	}
	out := make([]*extractors.SimplifiedNode, len(nodes))
	for i, n := range nodes {
		cloned := *n
		effectiveType := cloned.Type
		if effectiveType == "" && cloned.Template != "" && elements != nil {
			if body, ok := elements[cloned.Template]; ok {
				effectiveType, _ = body["type"].(string)
			}
		}
		if IsNoiseName(cloned.Name, effectiveType) {
			cloned.Name = ""
		}
		if len(cloned.Children) > 0 {
			cloned.Children = StripNoiseNames(cloned.Children, elements)
		}
		out[i] = &cloned
	}
	return out
}
